git2md:git-branch-or-tag () 
{ 
    if [ "$1" ]; then
        git tag | grep $1 || bajl:fail no $1 tag;
    else
        git branch --show-current;
    fi
}
git2md:git-commit-to-js () 
{ 
    pretty='{ _XXX_comment_XXX_: _XXX_%s_XXX_, _XXX_commit_XXX_: _XXX_%H_XXX_ }';
    git log -${1:-1} --pretty="$pretty" | sed -e 's/"/\\"/g' -e 's/_XXX_/"/g'
}
