{ 
    local jq='"\n    " as $s
| (if $what == "repo" then split("/")[-1] else split("/")[7:] | join("/") end) as $p
| "[\($p)]:\($s)\(.)\($s)\"github.com \($what)\"\n"';
    bajl:self -Rr --arg what ${1:-file}
}
git2md:gr2md () 
{ 
